    for idx, case in enumerate(mock_cases, 1):
        print(f"\n==========================================")
        print(f"Executing Case {idx}: {case['case_name']}")
        print(f"==========================================")
        
        messages = prompt.format_messages(**case["inputs"])
        
        try:
            result = structured_llm.invoke(messages)
            result.goal_id = case["inputs"]["goal_id"]
            print(json.dumps(result.model_dump(), indent=2))
        except Exception as e:
            print(f"Error executing case {idx}: {e}")
